var b=[["Dashboard Eksekutif","Ringkasan data makro ketahanan pangan, luas lahan, dan grafik produksi komoditas utama daerah."],["Peta Geospasial GIS","Peta WebGIS interaktif batas wilayah, tutupan sawah, tegalan, kebun, sungai, dan jaringan jalan."],["Prediksi Panen Padi","Analisis produktivitas dan simulasi perkiraan hasil panen padi per kecamatan."],["Tanaman Pangan","Statistik luas tanam, luas panen, dan produksi padi sawah, padi ladang, serta aneka palawija."],["Kalender Tanam & LTT","Target Luas Tambah Tanam (LTT) dan jadwal kalender tanam padi per musim tanam dan per kecamatan."],["Hortikultura","Produksi sayuran (kentang Dieng, kubis, cabai), buah tahunan (salak pondoh, durian), dan tanaman biofarmaka."],["Perkebunan Rakyat","Luas areal dan produksi komoditas perkebunan khas (kopi robusta/arabika, teh, cengkeh, kelapa deres)."],["Peternakan & Keswan","Populasi ternak kecil (termasuk Domba Batur), ternak besar, unggas, serta produksi daging, telur, dan susu/kulit."],["Lalu Lintas Ternak & RPH","Arus keluar-masuk ternak, aktivitas pasar hewan, dan rekapitulasi pemotongan hewan di RPH."],["Ekosistem Usaha Peternakan","Pemetaan UMKM pakan ternak, poultry shop, usaha bersertifikat NKV, dan daya tampung lahan HPT."],["Perikanan Air Tawar","Data produksi 10 jenis ikan budidaya, luas kolam/minapadi, tangkap perairan umum, dan benih ikan."],["Komoditas Unggulan per Bidang","Pemeringkatan komoditas unggulan daerah dan komoditas nomor 1 per kecamatan dari data riil produksi."],["Valuasi Nilai Ekonomi","Estimasi valuasi nilai ekonomi produksi per sektor komoditas dan per wilayah kecamatan."],["Kesesuaian Lahan Multi-Sektor","Evaluasi kesesuaian lahan Tanaman Pangan, Hortikultura, dan Perkebunan berbasis tutupan sawah vs bukan sawah serta kelas S1-S3-N."],["Peta Kerentanan Pangan FSVA","Peta tematik 16 indikator ketahanan dan kerentanan pangan 278 desa se-Kabupaten Banjarnegara."],["Ketersediaan & Neraca Pangan","Rasio ketersediaan beras (produksi vs kebutuhan konsumsi per kapita) dan stok lumbung pangan."],["Rantai Pasok & Distribusi","Pemetaan sebaran sarana penggilingan padi (RMU) dan kesiapan jalur distribusi beras daerah."],["Fluktuasi Harga Pasar","Pemantauan perkembangan harga komoditas pangan pokok di pasar-pasar daerah Banjarnegara."],["Kelembagaan Petani","Direktori 2.687 Poktan, Gapoktan, KWT, serta Kelembagaan Ekonomi Petani (KEP) dan Posluhdes."],["Bantuan Pemerintah & Alsintan","Penyaluran bantuan alsintan, sarana produksi, dan hibah pertanian berupa uang dan barang fisik."],["Profil 20 Kecamatan","Profil statistik kewilayahan, luas penggunaan lahan, dan komoditas utama pada 20 kecamatan."],["Asisten Si Pertani (AI)","Konsultasi interaktif data pertanian Banjarnegara dan rekomendasi kebijakan berbasis data."],["Portal Dasbor Admin","Akses masuk staf dinas untuk memperbarui data 17 domain via Excel (upsert), memantau kesiapan data, dan log audit."],["Informasi Umum SISPERTANI","Profil sistem, landasan operasional, sumber data resmi dinas, dan informasi teknis."]];
var x=["Membuka dan membaca seluruh halaman publik data pertanian Banjarnegara.","Melihat peta interaktif batas desa, tutupan lahan sawah, ladang, sungai, dan jalan.","Mengeksplorasi grafik tren, diagram komparasi, dan tabel statistik komoditas.","Menggunakan filter pencarian, pilihan kecamatan, dan tahun evaluasi.","Mengecek kesesuaian lahan multi-sektor dan profil kerentanan pangan desa (FSVA).","Mengunduh dokumen panduan lengkap (DOCX) dan mencetak halaman laporan ke format PDF."];
