var C=[{"title":"Dashboard & Peta Spasial","body":"Halaman awal menampilkan ringkasan angka makro pertanian daerah, luas lahan sawah vs bukan sawah, dan peta geospasial. Gunakan layer peta untuk melihat batas administrasi desa, sebaran tutupan lahan, dan jaringan sungai/jalan."},{"title":"Kesesuaian Lahan Multi-Sektor (/suitability)","body":"Pilih tab sektor (Semua Sektor, Tanaman Pangan, Hortikultura, atau Perkebunan), lalu tentukan kecamatan dan tahun. Amati kartu KPI, radar karakteristik komoditas, grafik perbandingan volume, dan tabel matriks kelas kesesuaian lahan (S1 Sangat Sesuai, S2 Cukup Sesuai, S3 Marjinal, N Belum Diusahakan)."},{"title":"Peta Kerentanan Pangan FSVA (/fsva)","body":"Buka peta FSVA untuk melihat tingkat kerentanan pangan 278 desa se-Banjarnegara. Gunakan pemilih indikator (akses air, rasio konsumsi, kemiskinan, infrastruktur) untuk melihat sebaran desa prioritas 1 hingga prioritas 6."},{"title":"Komoditas Unggulan & Nilai Ekonomi","body":"Pilih bidang komoditas yang ingin dilihat. Sistem secara otomatis menghitung komoditas peringkat pertama per kecamatan dan estimasi nilai ekonomi produksi tanpa menggunakan data tiruan."},{"title":"Tanaman Pangan & Kalender Tanam","body":"Pantau produksi padi sawah vs ladang, panen palawija, serta simulasi perkiraan hasil panen. Periksa menu LTT & Katam untuk melihat target luas tambah tanam padi per musim tanam."},{"title":"Hortikultura & Perkebunan","body":"Pelajari komoditas sayuran dataran tinggi (kentang Dieng, kubis, wortel), buah tahunan (salak pondoh, durian), biofarmaka (kapulaga, jahe), serta perkebunan rakyat (kopi robusta/arabika, teh, cengkeh, kelapa deres)."},{"title":"Peternakan & Perikanan Air Tawar","body":"Lihat data populasi ternak (termasuk plasma nutfah Domba Batur), produksi daging, telur, susu/kulit, sebaran UMKM pakan, arus lalu lintas ternak, dan pemotongan RPH. Pada menu perikanan, amati produksi 10 jenis ikan budidaya dan benih."},{"title":"Kelembagaan Tani & Bantuan Sarpras","body":"Telusuri direktori 2.687 kelompok tani binaan (Poktan, Gapoktan, KWT) berdasarkan kecamatan. Pada menu Bantuan, pantau sebaran penyaluran bantuan alsintan dan sarana produksi pemerintah."},{"title":"Profil 20 Kecamatan (/kecamatan)","body":"Pilih kecamatan dari peta atau menu dropdown untuk melihat profil kewilayahan, luas penggunaan tanah, komoditas unggulan setempat, dan kontak penyuluhan pertanian terkait."},{"title":"Portal Dasbor Admin Dinas (/admin)","body":"Khusus petugas dan penanggung jawab bidang teknis dinas: Masuk menggunakan akun bidang masing-masing, unduh template Excel terstandar, unggah pembaruan data (upsert), dan pantau matriks kesiapan data 17 domain."}];
